    97  uint16_t get_buffer(const uint8_t **buf, size_t buf_len, const uint8_t **out, size_t *out_len, size_t max_size)
    98  {
    99          /* Split buf into two parts according to length stored in first two bytes */
   100          uint16_t len = 0;
   101
   102          if (!buf || !(*buf) || buf_len < sizeof(uint16_t))
   103                  return 0;
   104
   105          /* Get length of the result buffer*/
   106          len = *((uint16_t *) *buf) % max_size;
   107          (*buf) += 2;
   108          buf_len -= 2;
   109          if (buf_len <= len) {
   110                  *out = *buf;
   111                  *out_len = buf_len;
   112                  return 0;
   113          }
   114
   115          /* Set out buffer to new reader data*/
   116          *out = *buf + len;
   117          *out_len = buf_len - len;
   118          return len;
   119  }
