   121  int create_input_file(char **filename_out, const uint8_t **data, size_t *size)
   122  {
   123          const uint8_t *ptr = *data;
   124          size_t file_size = 0, backup_size = *size;
   125          int fd = 0;
   126          size_t r = 0;
   127          char *filename = NULL;
   128
   129          /* Split data into file content and rest*/
   130          file_size = get_buffer(&ptr, *size, data, size, 6000);
   131          if (file_size == 0)
   132                  return 1;
   133
   134          filename = strdup("/tmp/input.XXXXXX");
   135          fd = mkstemp(filename);
   136          if (fd < 0) {
   137                  *data = ptr - 2;
   138                  *size = backup_size;
   139                  free(filename);
   140                  return 1;
   141          }
   142
   143          r = write(fd, ptr, file_size);
   144          close(fd);
   145
   146          if (r != file_size) {
   147                  *data = ptr - 2;
   148                  *size = backup_size;
   149                  remove_file(filename);
   150                  return 1;
   151          }
   152
   153          *filename_out = filename;
   154          return 0;
   155  }
